code='''from collections import deque

def components(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==color and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            out.append((color,cells))
    return out

def has_hole(cells):
    minr=min(r for r,c in cells); maxr=max(r for r,c in cells)
    minc=min(c for r,c in cells); maxc=max(c for r,c in cells)
    occupied=set(cells); seen=set(); q=deque()
    for r in range(minr,maxr+1):
        for c in (minc,maxc):
            if (r,c) not in occupied and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(minc,maxc+1):
        for r in (minr,maxr):
            if (r,c) not in occupied and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if minr<=nr<=maxr and minc<=nc<=maxc and (nr,nc) not in occupied and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return any((r,c) not in occupied and (r,c) not in seen for r in range(minr,maxr+1) for c in range(minc,maxc+1))

def transform(grid):
    h,w=len(grid),len(grid[0]); objs=[]
    for color,cells in components(grid):
        objs.append({'color':color,'cells':cells,'up':has_hole(cells)})
    # Compact hole-containing objects toward the top and the other objects toward the bottom.
    for direction in ('up','down'):
        group=[o for o in objs if o['up']==(direction=='up')]
        group.sort(key=lambda o: min(r for r,c in o['cells']) if direction=='up' else -max(r for r,c in o['cells']))
        settled=[]
        for obj in group:
            cells=obj['cells']; dr=-1 if direction=='up' else 1
            while True:
                moved=[(r+dr,c) for r,c in cells]
                if any(r<0 or r>=h for r,c in moved): break
                if any((r,c) in set(q for other in settled for q in other['cells']) for r,c in moved): break
                cells=moved
            obj['cells']=cells; settled.append(obj)
    out=[[0]*w for _ in range(h)]
    for obj in objs:
        for r,c in obj['cells']: out[r][c]=obj['color']
    return out
'''
